 /********************************************************************************************
 * @Writer
 *  김동진 2025.04.02
 *
 * @Description
 * 	계기함(MB)
 *
 * @Syntax
 * 	<mobmtr4004></mobmtr4004>
 *
 * @Parameters
 *  detail : 상세정보
 *  codeList : 공통코드
 ********************************************************************************************/

Vue.component('mobmtr4004', {
	props:['detail', 'codeList', 'status', 'insunit'],
	data: function() {
		return {
			activeTab: 1,
			messageModal: new ModalSet('modal-message'),
			vFlmnCl: '',
			cachedDetail: null,
        };
    },
    template: `
	<div class="grow d-flex">
	    <button style="height: 54px !important;" type="button" :style="{ background: detail[status+'MB_YN'] === 'Y' ? '#427FDF' : '', color: detail[status+'MB_YN'] === 'Y' ? '#FFF' : '' }" class="btn type01 size-m c-bluegray grow b-flex" @click="openMbModal">계기함<br>(M/B)</button>
	    <transition name="fade">
	        <div class="modal-layer-wrap">
	            <div id="modal_mb" class="modal-layer type02">
	                <div class="modal-container">
	                    <div class="modal-header">
	                        <p class="modal-title">계기함</p>
	                    </div>
	                    <div class="modal-content">
							<!--
	                        <table class="table-type35" v-if="insunit != '40'">
	                            <caption>고객정보를 항목별 순서대로 안내하는 표입니다</caption>
	                            <colgroup>
	                                <col width="20%">
	                                <col width="30%">
	                                <col width="20%">
	                                <col width="30%">
	                            </colgroup>
	                            <tbody>
	                                <tr>
	                                    <th scope="row">고객번호</th>
	                                    <td colspan="3">
	                                        {{ detail.CNTR_NO }}
	                                    </td>
	                                </tr>
	                                <tr>
	                                    <th scope="row">계약전력</th>
	                                    <td>
	                                        {{ detail.CNTR_PWR }}
	                                    </td>
	                                    <th scope="row">계기번호</th>
	                                    <td>
	                                        {{ detail.WHM_NO }}
	                                    </td>
	                                </tr>
	                                <tr>
	                                    <th scope="row">주소</th>
	                                    <td colspan="3">
	                                        {{ detail.WRK_PLCE_ADDR_CTT }}
	                                    </td>
	                                </tr>
	                            </tbody>
	                        </table>
							-->
							<table class="table-type35" v-if="detail.REG_ID != session.USER_ID && typeof detail.REG_ID !== 'undefined'">
							    <caption>고객정보를 항목별 순서대로 안내하는 표입니다</caption>
							    <colgroup>
							        <col width="100%">
							    </colgroup>
							    <tbody>
							        <tr>
							            <td>
							                [{{ detail.CNTR_NO }}][{{ detail.CNTR_PWR }}][{{ detail.WHM_NO }}][{{ detail.WRK_PLCE_ADDR_CTT }}]
							            </td>
							        </tr>
							    </tbody>
							</table>

	                        <div class="tab-outter">
	                            <div class="tab-type05">
	                                <div class="tab-inner">
	                                    <div rel="tab1"><a href="#!" :class="{'active' : activeTab == 1}" @click="activeTab = 1">계기함(M/B)</a></div>
	                                </div>
	                            </div>
	                        </div>
	                        <div class="tab-container type05">
	                            <div id="tab1" class="tab-content" v-if="activeTab == 1">
	                                <div class="inner-box">
	                                    <table class="table-type33">
	                                        <caption>계기함(M/B) 정보를 항목별 순서대로 안내하는 표입니다</caption>
	                                        <colgroup>
	                                            <col width="20%">
	                                            <col width="30%">
	                                            <col width="20%">
	                                            <col width="30%">
	                                        </colgroup>
	                                        <tbody>
	                                            <tr>
	                                                <th scope="row"><label for="form0101">자재번호</label></th>
	                                                <td colspan="3">
	                                                    <!--<div class="flex">
	                                                        <input v-model="detail[status+'MB_MATL_NO']" type="text" maxlength="20" id="form0101" class="size-m">
	                                                    </div>-->
														<select v-model="detail[status+'MB_MATL_NO']" id="form0101" class="size-m">
														    <option value="">선택</option>
														    <option v-for="item in codeList.rawData.filter(item => item.P_CODE == 'MTR009')" :value="item.C_CODE">{{ item.C_CODE+'/'+ item.C_CODE_NM }}</option>
														</select>
	                                                </td>
	                                            </tr>
	                                            <template v-if="status == 'C'">
	                                            <tr>
	                                                <th scope="row"><label for="form0104">소유구분</label></th>
	                                                <td colspan="3">
	                                                    <select v-model="detail.CMB_POSS_CLCD" id="form0104" class="size-m">
	                                                        <option value="">선택</option>
	                                                        <option v-for="item in codeList.rawData.filter(item => item.P_CODE == 'JC015')" :value="item.C_CODE">{{ item.C_CODE_NM }}</option>
	                                                    </select>
	                                                </td>
	                                            </tr>
	                                            </template>
	                                            <template v-if="status == 'D'">
	                                            <tr>
	                                                <th scope="row"><label for="form0102">철거사유</label></th>
	                                                <td colspan="3">
	                                                    <select v-model="detail.DMB_DISM_RSN_CD" id="form0102" class="size-m">
	                                                        <option value="">선택</option>
	                                                        <option v-for="item in codeList.rawData.filter(item => item.P_CODE == 'JA041')" :value="item.C_CODE">{{ item.C_CODE_NM }}</option>
	                                                    </select>
	                                                </td>
	                                            </tr>
	                                            <tr>
	                                                <th scope="row"><label for="form0103">환입구분</label></th>
	                                                <td colspan="3">
	                                                    <select v-model="detail.DMB_PURC_CLCD" id="form0103" class="size-m">
	                                                        <option value="">선택</option>
	                                                        <option v-for="item in codeList.rawData.filter(item => item.P_CODE == 'YZ016')" :value="item.C_CODE">{{ item.C_CODE_NM }}</option>
	                                                    </select>
	                                                </td>
	                                            </tr>
	                                            </template>
	                                        </tbody>
	                                    </table>
	                                </div>
	                                <div class="btn-line d-flex between">
	                                    <button type="button" class="btn type01 size-m c-primary" @click="closeMbModal">취소</button>
	                                    <button type="button" class="btn type01 size-m c-primary" @click="messagePopup('25')">임시저장</button>
	                                </div>
	                            </div>
	                        </div>
	                    </div>
	                    <div class="btn-r">
	                        <a href="#" class="cbtn" style="display: inline-block;" title="닫기" @click="closeMbModal"><span class="icon-exit"></span></a>
	                    </div>
	                </div>
	            </div>
	        </div>
	    </transition>
	    <modal-message :modalset="messageModal" v-on:messagepoppupcallback="messagePopupCallback"></modal-message>
		<barcode-reader ref="barcodeReader" id="barcode_reader" title="바코드 테스트" @callback="receiveBarcode"></barcode-reader>
	</div>
    `,
	mounted: function() {
		
	},
	methods: {
		init: function(){
			if(this.detail[this.status+'MB_YN'] !== 'Y'){
				this.detail.DMB_DISM_RSN_CD = '1';
				this.detail.DMB_PURC_CLCD = '4';
				this.detail.CMB_POSS_CLCD = '1';
			}
		},
		callBackEvent: function(){
			this.$emit('callbackevt', -1);
		},
		messagePopup: function(pId) {
			var title = '확인';
			var cont = '해당 작업을 수행하시겠습니까?';
			switch(pId) {
				case '25':
					title = '임시저장';
					cont = '변경 사항을 임시저장하시겠습니까?';
					break;
			}
			this.messageModal.openModal('confirm', title, cont, 'small', pId);
		},
		messagePopupCallback: function(pGb, pId) {
			if(pGb!='confirm') return;
			this.validateRow(pId);
		},
		validateRow: function(pId){
			var self = this;
			var validate = this.$validator.validateAll();
			validate.then(function(response){
				if(response){
			        self.saveRow(pId);
			    }else {
				    self.$validator.errors.items.forEach(function(error) {
					    var fieldName = error.field; 
					    var inputElement = self.$refs[fieldName];
					    if (inputElement) {
					        inputElement.focus();
					        return; 
					    }
				    });
				}
			});
		},	
		saveRow: function(pId){
			var self = this;
			self.detail.STATUS = self.status;
			var params = _.cloneDeep(self.detail);
			params.EX_WORK_STEP = self.detail.WORK_STEP;						
			params.WORK_STEP = pId;
			var returnVal;

			document.getElementById("sub_header").style.zIndex = 701;
			document.getElementById("header").style.zIndex = 1000;
			self.detail[self.status+'MB_YN'] = 'Y';
			modal_close('modal_mb');
		},
		readBarcode: function(gubun){ 
		    this.vFlmnCl = gubun;
		    this.$refs.barcodeReader.openBarcodeScanner("1d");
		},
		receiveBarcode: function(){
		    var vBarcdQr = this.$refs.barcodeReader.readValue;
			this.detail[this.vFlmnCl] = vBarcdQr;
		},
		openMbModal: function() {
		    this.cachedDetail = _.cloneDeep(this.detail);
			document.getElementById("sub_header").style.zIndex = 0;
			document.getElementById("header").style.zIndex = 0;
			this.init();
		    modal_open('modal_mb');
		},
		closeMbModal: function() {
		    if (this.cachedDetail) {
		        Object.assign(this.detail, this.cachedDetail);
		    }
			document.getElementById("sub_header").style.zIndex = 701;
			document.getElementById("header").style.zIndex = 1000;
		    modal_close('modal_mb');
		},
	}

 });

